# IMPOSSIBLE: Set brightness on guest bedroom light (guestBedroomLight has no brightness control - only turnOn/turnOff and state)
# IMPOSSIBLE: Decrease study room heating temperature by 7 degrees to 14 (studyRoomAirConditioner supports set_temperature in range 16-30; 14 is out of range)
# IMPOSSIBLE: Set heating temperature to 24 in master bedroom (masterBedroomHeating has no set_temperature action)
# IMPOSSIBLE: Lower the air conditioner temperature by 5 degrees in the living room (no air conditioner device in living_room; only livingRoomHeating exists and the user explicitly requested air conditioner)

# Behavior tree executing the achievable actions in parallel
tree = py_trees.composites.Parallel(
    name="ExecuteAdjustments",
    policy=py_trees.common.ParallelPolicy.SuccessOnAll(),
    children=[
        ActionAffordanceNode(
            name="SetStudyACTo20",
            action_url="http://localhost:8080/workspaces/home73/study_room/artifacts/studyRoomAirConditioner/set_temperature",
            parameters={"temperature": 20}
        ),
        ActionAffordanceNode(
            name="SetMasterFanSpeedToMedium",
            action_url="http://localhost:8080/workspaces/home73/master_bedroom/artifacts/masterBedroomHeating/set_fan_speed",
            parameters={"fan_speed": "medium"}
        ),
        ActionAffordanceNode(
            name="SetBalconyBrightnessTo100",
            action_url="http://localhost:8080/workspaces/home73/balcony/artifacts/balconyLight/set_brightness",
            parameters={"brightness": 100}
        ),
        ActionAffordanceNode(
            name="IncreaseStudyHumidifierIntensityBy13",
            action_url="http://localhost:8080/workspaces/home73/study_room/artifacts/studyRoomHumidifier/set_intensity",
            # current intensity is 47; increase by 13 -> 60
            parameters={"intensity": 60}
        ),
    ]
)
